using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using CosmicBlock.UI;
using CosmicBlock.Core;
using CosmicBlock.Blocks;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
public static class GameMeshProbe {
 static double began;static int frames,count;static string errors="",warnings="";static GameFlowController flow;static GameSession session;static Dictionary<string,int> saved=new Dictionary<string,int>();static List<string> keys=new List<string>(),results=new List<string>();
 public static void Run(){RunSaveStore.PathOverride=Path.GetFullPath("Validation/game-mesh-isolated.json");keys.Add(GameSession.DefaultBestScoreKey);keys.Add(PlanetSelection.Key);keys.Add(PlanetRestoration.VersionKey);foreach(var d in PlanetDefinitions.All){keys.Add(d.EnergyKey);keys.Add(d.UnlockKey);keys.Add(PlanetCompletionNotice.Key(d.Id));}foreach(var k in keys){if(PlayerPrefs.HasKey(k))saved[k]=PlayerPrefs.GetInt(k);PlayerPrefs.DeleteKey(k);}PlayerPrefs.SetInt(PlanetRestoration.VersionKey,2);PlayerPrefs.SetInt(PlanetRestoration.DefaultKey,190);PlayerPrefs.SetInt(GameSession.DefaultBestScoreKey,19000);PlayerPrefs.Save();EditorSceneManager.OpenScene("Assets/Scenes/Game.unity");began=EditorApplication.timeSinceStartup;Application.logMessageReceived+=Log;EditorApplication.update+=Check;EditorApplication.EnterPlaymode();}
 static void Check(){if(EditorApplication.timeSinceStartup-began>240){Finish(false,"timeout");return;}if(!EditorApplication.isPlaying||++frames<40)return;EditorApplication.update-=Check;RunSaveStore.PathOverride=Path.GetFullPath("Validation/game-mesh-isolated.json");RunSaveStore.Delete();flow=UnityEngine.Object.FindAnyObjectByType<GameFlowController>();session=UnityEngine.Object.FindAnyObjectByType<GameSession>();flow.ShowHome();flow.RefreshHome();session.StartCoroutine(Guard());}
 static IEnumerator Guard(){var tests=Tests();while(true){object value;try{if(!tests.MoveNext())break;value=tests.Current;}catch(Exception e){Finish(false,e.ToString());yield break;}yield return value;}Finish(errors.Length==0&&warnings.Length==0,errors+warnings);}

 static IEnumerator Tests(){
  flow.StartNewRun();yield return null;
  var safe=flow.HomeRoot.transform.parent;var mesh=safe.Find("GameScorePresentation").GetComponent<GameMeshPresentation>();var visual=mesh.GetComponent<GameVisualPresentation>();var planet=UnityEngine.Object.FindAnyObjectByType<PlanetRestorationView>();var ui=UnityEngine.Object.FindAnyObjectByType<GameAssistView>();
  var fixture=UnityEngine.Object.FindAnyObjectByType<CosmicBlock.Board.BoardView>();int[] cells=new int[64];for(int i=0;i<64;i++)cells[i]=-1;foreach(int i in new[]{0,1,2,20,21,28})cells[i]=2;foreach(int i in new[]{8,9,12,13,36,37})cells[i]=1;foreach(int i in new[]{18,19,40,48,54,55})cells[i]=0;fixture.RestoreCells(cells);foreach(int h in new[]{1920,2400,1440})Capture(h,"ready");
  foreach(var d in PlanetDefinitions.All){PlayerPrefs.SetInt(d.UnlockKey,1);PlanetSelection.Select(d.Id);session.LoadSelectedPlanet();planet.ResetTransient();planet.Render(session.Restoration,false);foreach(float value in new[]{0f,.25f,.5f,.75f,.99f,1f}){planet.RenderEnergy(Mathf.RoundToInt(d.Total*value),false);visual.RefreshVisual();mesh.Apply();var fill=(RectTransform)safe.Find("PlanetRestoration/ProgressBar/Fill");Req(Mathf.Abs(fill.anchorMax.x-value)<.001f,"기존 전체 복원도/메시 Fill "+d.Id+" "+value);Req(fill.GetComponentInChildren<HomeQuitMeshGraphic>()!=null,"메시 Fill 표시");} }
  PlanetSelection.Select(1);session.LoadSelectedPlanet();session.Retry();
  var board=UnityEngine.Object.FindAnyObjectByType<CosmicBlock.Board.BoardView>();var layer=(RectTransform)safe.parent.Find("DragLayer");
  foreach(var shape in BlockCatalog.Shapes){session.Retry();var piece=session.Slots[0];piece.Initialize(shape,board,layer,session);Canvas.ForceUpdateCanvases();var slot=piece.transform.parent.GetComponent<SlotDragHandler>();var r=(RectTransform)slot.transform;var data=new PointerEventData(EventSystem.current){pointerId=-1,position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.min+Vector2.one*10))};slot.OnBeginDrag(data);Req(piece.GetComponent<BlockDragHandler>().IsDragging,"Slot 가장자리 드래그 "+shape.Id);var handler=piece.GetComponent<BlockDragHandler>();float pitch=board.CellSize+board.CellSpacing;var center=board.GetCellWorld(new Vector2Int(1,1))+layer.TransformVector(new Vector3((shape.Width-1)*pitch/2,-(shape.Height-1)*pitch/2-session.DragFingerOffset));var drop=new PointerEventData(EventSystem.current){pointerId=-1,position=RectTransformUtility.WorldToScreenPoint(null,center)};handler.OnDrag(drop);Req(board.PreviewValid&&board.PreviewCount==shape.Cells.Count&&piece.DragHighlightActive,"유효 Preview/Gold "+shape.Id);handler.OnEndDrag(drop);Req(piece.IsConsumed,"Shape Drag 배치 "+shape.Id);Req(!slot.IsInteractable,"Consumed Slot 입력 차단");}
  session.Retry();board.Model.SetOccupied(1,1,true);var invalid=session.Slots[0];invalid.Initialize(BlockCatalog.Shapes[0],board,layer,session);var invalidHandler=invalid.GetComponent<BlockDragHandler>();var invalidData=new PointerEventData(EventSystem.current){pointerId=-1,position=RectTransformUtility.WorldToScreenPoint(null,board.GetCellWorld(new Vector2Int(1,1))-layer.TransformVector(new Vector3(0,session.DragFingerOffset)))};invalidHandler.OnBeginDrag(invalidData);Req(!board.PreviewValid,"무효 Preview");invalidHandler.OnEndDrag(invalidData);Req(!invalid.IsConsumed,"무효 배치 복귀");session.Retry();session.DebugPrepareNextRow();Req(session.TryHint(),"힌트 기존 기능");Req(ui.HighlightCount>0,"힌트 셀 표시");session.ClearHint();yield return new WaitForSecondsRealtime(.3f);Req(session.TryRefreshBlocks(),"새로고침 기존 기능");ui.SendMessage("LateUpdate");mesh.Apply();foreach(int h in new[]{1920,2400,1440})Capture(h,"used");
  session.DebugPrepareNextRow();Req(session.TryPlacePiece(session.Slots[0],3,3),"라인 클리어");session.DebugCompleteTurnForProbe();flow.RequestHome();Req(flow.HomeConfirmVisible,"HOME 확인");flow.CancelHome();Req(flow.Screen==FlowScreen.Game,"HOME 취소");flow.RequestHome();flow.ConfirmHome();yield return null;string savedRun=File.ReadAllText(RunSaveStore.SavePath);int score=session.Score;flow.Play();Req(session.Score==score&&File.ReadAllText(RunSaveStore.SavePath)==savedRun,"이어하기 Score/Run 보존");session.DebugForceGameOver();Req(session.State==GameState.GameOver,"Game Over");session.Retry();Req(session.Score==0&&session.State==GameState.Playing,"Retry");
  results.Add("PASS 전체 Shape/Slot Drag/Consumed/Hint/Refresh/Clear/HOME/Resume/GameOver/Retry");
 }
 static void Capture(int h,string state){
  var canvas=GameObject.Find("GameCanvas").GetComponent<Canvas>();var safe=(RectTransform)flow.HomeRoot.transform.parent;var sa=safe.GetComponent<SafeArea>();var cam=Camera.main;var rt=new RenderTexture(1080,h,24);var mode=canvas.renderMode;var camera=canvas.worldCamera;var target=cam.targetTexture;var active=RenderTexture.active;bool enabled=sa.enabled;var min=safe.anchorMin;var max=safe.anchorMax;Texture2D tex=null;
  try{sa.enabled=false;rt.Create();cam.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=10;safe.anchorMin=h==2400?new Vector2(.02f,.04f):Vector2.zero;safe.anchorMax=h==2400?new Vector2(.98f,.94f):Vector2.one;safe.offsetMin=safe.offsetMax=Vector2.zero;Canvas.ForceUpdateCanvases();
   var visual=safe.Find("GameScorePresentation").GetComponent<GameVisualPresentation>();var mesh=visual.GetComponent<GameMeshPresentation>();var ui=UnityEngine.Object.FindAnyObjectByType<GameAssistView>();visual.RefreshVisual();ui.SendMessage("LateUpdate");mesh.Apply();Canvas.ForceUpdateCanvases();foreach(var piece in session.Slots)piece.FitSlot();Canvas.ForceUpdateCanvases();
   var board=(RectTransform)safe.Find("Board");var dims=board.rect.size;visual.Layout();Canvas.ForceUpdateCanvases();Req(Vector2.Distance(dims,board.rect.size)<.01f,"메시 교체 전후 Board 크기 유지");mesh.Apply();Canvas.ForceUpdateCanvases();Rect bounds=World(safe);var paths=new[]{"PlayingHomeButton","PlanetRestoration","BoardFrame/MeshSurface","BlockArea","GameScorePresentation/BestFrameArea"};
   foreach(var path in paths)Req(Inside(bounds,World((RectTransform)safe.Find(path))),"SafeArea "+path+" "+h);
   Req(!World((RectTransform)safe.Find("GameScorePresentation/BestFrameArea")).Overlaps(World(visual.ScoreText.rectTransform)),"BEST/SCORE 겹침 없음");
   foreach(var button in new[]{ui.RefreshButton,ui.HintButton}){Req(button.targetGraphic is HomeQuitMeshGraphic,"기능 버튼 메시");var rect=(RectTransform)button.transform;Req(Inside(bounds,World(rect)),"버튼 SafeArea");foreach(var piece in session.Slots)Req(!World(rect).Overlaps(World((RectTransform)piece.transform.parent)),"Slot/버튼 Hit 분리");}
   foreach(int v in new[]{0,19000,999999,int.MaxValue}){visual.RenderValues(v,v);mesh.Apply();visual.ScoreText.ForceMeshUpdate();visual.BestText.ForceMeshUpdate();Req(!visual.ScoreText.isTextOverflowing&&!visual.BestText.isTextOverflowing,"큰 점수 잘림 없음 "+v+" "+h);}
   visual.RenderValues(1670,19000);mesh.Apply();
   foreach(var text in safe.Find("PlanetRestoration").GetComponentsInChildren<TMP_Text>(true)){text.ForceMeshUpdate();Req(text.font.HasCharacters(text.text)&&!text.isTextOverflowing,"HUD 글리프/잘림 "+text.name);}
   foreach(var text in ui.Root.GetComponentsInChildren<TMP_Text>(true)){text.ForceMeshUpdate();Req(text.font.HasCharacters(text.text)&&!text.isTextOverflowing,"기능 버튼 글리프/잘림 "+text.name);}
   foreach(var bg in canvas.GetComponentsInChildren<AspectFillBackground>(true)){var r=(RectTransform)bg.transform;var reference=new SerializedObject(bg).FindProperty("referenceSize").vector2Value;var full=(RectTransform)canvas.transform;r.sizeDelta=reference*Mathf.Max(full.rect.width/reference.x,full.rect.height/reference.y);r.anchoredPosition=((RectTransform)r.parent).InverseTransformPoint(full.TransformPoint(full.rect.center));}Canvas.ForceUpdateCanvases();foreach(var cell in safe.Find("Board").GetComponentsInChildren<GameEmptyCellMesh>())cell.SendMessage("LateUpdate");cam.Render();
   foreach(var button in new[]{ui.RefreshButton,ui.HintButton,safe.Find("PlayingHomeButton").GetComponent<Button>()}){var rect=(RectTransform)button.transform;var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(cam,rect.TransformPoint(rect.rect.center))},hits);Req(hits.Count>0&&hits[0].gameObject.transform.IsChildOf(rect),"실제 Button Raycast");}
   foreach(var piece in session.Slots){if(piece.IsConsumed)continue;var rect=(RectTransform)piece.transform.parent;foreach(var local in new[]{rect.rect.min+Vector2.one*10,rect.rect.max-Vector2.one*10}){var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(cam,rect.TransformPoint(local))},hits);Req(hits.Count>0&&hits[0].gameObject.transform.IsChildOf(rect),"Slot 빈 공간 실제 Raycast");}}RenderTexture.active=rt;tex=new Texture2D(1080,h,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1080,h),0,0);tex.Apply();File.WriteAllBytes("Validation/game_mesh_"+state+"_"+h+".png",tex.EncodeToPNG());results.Add("PASS "+h+" "+state+" Board="+board.rect.size+" SafeArea/큰 점수/터치/폰트");
  }finally{canvas.renderMode=mode;canvas.worldCamera=camera;cam.targetTexture=target;RenderTexture.active=active;safe.anchorMin=min;safe.anchorMax=max;sa.enabled=enabled;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
 }
 static Rect World(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return Rect.MinMaxRect(c[0].x,c[0].y,c[2].x,c[2].y);}static bool Inside(Rect a,Rect b)=>b.xMin>=a.xMin-.1f&&b.yMin>=a.yMin-.1f&&b.xMax<=a.xMax+.1f&&b.yMax<=a.yMax+.1f;
 static void Req(bool b,string m){count++;if(!b)throw new Exception(m);}static void Log(string m,string s,LogType t){if(t==LogType.Warning)warnings+=m+"\n";if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors+=m+"\n";}
 static void Finish(bool pass,string failure){EditorApplication.update-=Check;Application.logMessageReceived-=Log;if(session!=null)session.LeaveForHome();RunSaveStore.Delete();foreach(var k in keys){if(saved.TryGetValue(k,out int value))PlayerPrefs.SetInt(k,value);else PlayerPrefs.DeleteKey(k);}PlayerPrefs.Save();File.WriteAllText("Validation/game_mesh_tests.txt",string.Join("\n",results)+"\nAssertions="+count+"\nWarnings="+warnings+"\nErrors="+errors+"\n"+(pass?"GAME_MESH_PASS":failure));EditorApplication.Exit(pass?0:1);}
}
